/**
 * FC Navigation -- section behaviour.
 *
 * GENERATED by tools/uew from founders-circle-revamp/section-00-nav.html. Do not edit by hand.
 *
 * The section's original script bodies are reproduced verbatim inside
 * uewRun(). What is added around them is the Elementor lifecycle: widgets are
 * injected into the editor canvas long after DOMContentLoaded, so a bare IIFE
 * would query an element that does not exist yet and the section would look
 * "broken" in the editor. Registering on frontend/element_ready fixes that, and
 * the data-uew-ready latch keeps a double call harmless.
 */
( function () {
	'use strict';

	var ROOT_SELECTOR = "#fcNavBar";
	var WIDGET_NAME = "umoya-fc-nav";

	function uewRun() {
		(function(){
		    'use strict';

		    var bar      = document.getElementById('fcNavBar');
		    var burger   = document.getElementById('fcNavBurger');
		    var dropdown = document.getElementById('fcNavDropdown');

		    if(!bar) return;

		    /* ── PIN / REVEAL — slide the fixed bar in once the hero is past ─ */
		    var hero = document.getElementById('fc-hero');

		    function setPinned(on){
		      bar.classList.toggle('fc-nav-pinned', !!on);
		    }

		    if(hero && 'IntersectionObserver' in window){
		      var pinObs = new IntersectionObserver(function(entries){
		        /* hero out of view → show bar; hero visible → hide bar */
		        setPinned(!entries[0].isIntersecting);
		      }, { threshold: 0 });
		      pinObs.observe(hero);
		    } else {
		      var pinFallback = function(){
		        var past = hero
		          ? (hero.getBoundingClientRect().bottom <= 0)
		          : (window.pageYOffset > 300);
		        setPinned(past);
		      };
		      window.addEventListener('scroll', pinFallback, { passive: true });
		      pinFallback();
		    }

		    /* ── HAMBURGER TOGGLE ───────────────────────────────────── */
		    function open(){
		      bar.classList.add('fc-open');
		      dropdown.classList.add('fc-mob-open');
		      burger.setAttribute('aria-expanded','true');
		      burger.setAttribute('aria-label','Close navigation menu');
		    }

		    function close(){
		      bar.classList.remove('fc-open');
		      dropdown.classList.remove('fc-mob-open');
		      burger.setAttribute('aria-expanded','false');
		      burger.setAttribute('aria-label','Open navigation menu');
		    }

		    if(burger){
		      burger.addEventListener('click', function(){
		        bar.classList.contains('fc-open') ? close() : open();
		      });
		      burger.addEventListener('keydown', function(e){
		        if(e.key === 'Enter' || e.key === ' '){ e.preventDefault(); burger.click(); }
		      });
		    }

		    /* Close on any dropdown link or CTA tap */
		    if(dropdown){
		      dropdown.querySelectorAll('a').forEach(function(a){
		        a.addEventListener('click', function(){ close(); });
		      });
		    }

		    /* Close when clicking outside the bar */
		    document.addEventListener('click', function(e){
		      if(!bar.contains(e.target)) close();
		    });

		    /* ── ACTIVE SECTION TRACKING ────────────────────────────── */
		    var ids = [
		      'fc-intro',
		      'fc-benefits',
		      'fc-form-section',
		      'fc-journey',
		      'fc-why',
		      'fc-details'
		    ];

		    function setActive(activeId){
		      ids.forEach(function(id){
		        /* desktop items */
		        var desktopItem = bar.querySelector('.fc-nav-item[data-s="' + id + '"]');
		        if(desktopItem) desktopItem.classList.toggle('fc-active', id === activeId);
		        /* mobile dropdown items */
		        var mobileItem = bar.querySelector('.fc-nav-dropdown-item[data-s="' + id + '"]');
		        if(mobileItem) mobileItem.classList.toggle('fc-active', id === activeId);
		      });
		    }

		    if('IntersectionObserver' in window){
		      var obs = new IntersectionObserver(function(entries){
		        entries.forEach(function(entry){
		          if(entry.isIntersecting) setActive(entry.target.id);
		        });
		      },{
		        rootMargin: '-64px 0px -50% 0px',
		        threshold: 0
		      });
		      ids.forEach(function(id){
		        var el = document.getElementById(id);
		        if(el) obs.observe(el);
		      });
		    }

		    /* ── SMOOTH SCROLL ──────────────────────────────────────── */
		    var navH = bar.offsetHeight || 64;

		    /* Logo — always scrolls to the very top of the page */
		    var logoLink = bar.querySelector('.fc-nav-logo');
		    if(logoLink){
		      logoLink.addEventListener('click', function(e){
		        e.preventDefault();
		        'scrollBehavior' in document.documentElement.style
		          ? window.scrollTo({top: 0, behavior: 'smooth'})
		          : window.scrollTo(0, 0);
		      });
		    }

		    /* All other hash links — offset by nav height */
		    bar.querySelectorAll('a[href^="#"]').forEach(function(a){
		      if(a.classList.contains('fc-nav-logo')) return; /* skip logo */
		      a.addEventListener('click', function(e){
		        var target = document.getElementById(a.getAttribute('href').slice(1));
		        if(!target) return;
		        e.preventDefault();
		        var top = target.getBoundingClientRect().top + window.pageYOffset - navH;
		        'scrollBehavior' in document.documentElement.style
		          ? window.scrollTo({top: top, behavior: 'smooth'})
		          : window.scrollTo(0, top);
		      });
		    });

		  }());
	}

	function uewInit( scope ) {
		var context = scope && scope.length ? scope[ 0 ] : ( scope || document );
		var root = context.querySelector ? context.querySelector( ROOT_SELECTOR ) : null;

		if ( ! root && context !== document && context.matches && context.matches( ROOT_SELECTOR ) ) {
			root = context;
		}
		if ( ! root ) {
			root = document.querySelector( ROOT_SELECTOR );
		}
		if ( ! root ) {
			return;
		}
		if ( root && root.getAttribute( 'data-uew-ready' ) === '1' ) {
			return;
		}
		if ( root ) {
			root.setAttribute( 'data-uew-ready', '1' );
		}

		uewRun();
	}

	function uewRegister() {
		if ( ! window.elementorFrontend || ! window.elementorFrontend.hooks ) {
			return false;
		}
		window.elementorFrontend.hooks.addAction( 'frontend/element_ready/' + WIDGET_NAME + '.default', uewInit );
		return true;
	}

	if ( ! uewRegister() ) {
		// Elementor fires this through jQuery, not as a native DOM event, so a
		// plain addEventListener would never hear it.
		if ( window.jQuery ) {
			window.jQuery( window ).on( 'elementor/frontend/init', uewRegister );
		} else {
			window.addEventListener( 'elementor/frontend/init', uewRegister );
		}
	}

	// Plain page load (and any context where Elementor's frontend never boots).
	if ( document.readyState === 'loading' ) {
		document.addEventListener( 'DOMContentLoaded', function () {
			uewInit( document );
		} );
	} else {
		uewInit( document );
	}
}() );
